import os

from amazon.textract import TextractClient


class DocumentClient:
    def __init__(self):
        self.textract_client = TextractClient(
            aws_access_key_id=os.getenv('AWS_ACCESS_KEY_ID'),
            aws_secret_access_key=os.getenv('AWS_SECRET_ACCESS_KEY'),
            region_name=os.getenv('AWS_REGION', 'us-west-2')
        )

    def extract_document(self, document):
        return self.textract_client.analyze_document(document)


def get_document_client():
    return DocumentClient()

import boto3

def validate_fields(document):
    textract = boto3.client('textract')
    response = textract.analyze_document(
        Document={'Bytes': document},
        FeatureTypes=['FORMS'])
    blocks = response['Blocks']
    required_fields = ['vendor', 'date', 'total']
    missing_fields = []
    low_confidence_fields = []
    for block in blocks:
        if block['BlockType'] == 'KEY_VALUE_SET':
            key = block['Text'] if 'Text' in block else ''
            if key.lower() in required_fields:
                value = next((child['Text'] for child in block['Relationships'][0]['Ids'] if child['BlockType'] == 'VALUE'), '')
                if not value:
                    missing_fields.append(key)
                elif block['Confidence'] < 70:
                    low_confidence_fields.append(key)
    return missing_fields, low_confidence_fields

import boto3

def normalize_expense(expense_data):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_expense_document(
        Document={'Bytes': expense_data}
    )
    normalized_expense = {}
    for document in response['ExpenseDocuments']:
        for line_item in document['LineItems']:
            normalized_expense[line_item['LineItemExpenseFields']] = line_item['ValueDetection']['Text']
    return normalized_expense

import boto3

def extract_receipt_fields(receipt_image):
    textract_client = boto3.client('textract')
    response = textract_client.analyze_document(
        Document={'Bytes': receipt_image},
        FeatureTypes=['FORMS'])
    merchant = None
    tax = None
    total = None
    items = []
    for block in response['Blocks']:
        if block['BlockType'] == 'KEY_VALUE_SET':
            if 'Merchant' in block['Text']:
                merchant = block['Text'].replace('Merchant', '').strip()
            elif 'Tax' in block['Text']:
                tax = block['Text'].replace('Tax', '').strip()
            elif 'Total' in block['Text']:
                total = block['Text'].replace('Total', '').strip()
        elif block['BlockType'] == 'LINE':
            items.append(block['Text'].strip())
    return {
        'merchant': merchant,
        'tax': tax,
        'total': total,
        'items': items
    }

import boto3

class InvoiceExtractor:
    def __init__(self):
        self.textract_client = boto3.client('textract')

    def extract_fields(self, document_path):
        with open(document_path, 'rb') as document:
            image_bytes = document.read()

        response = self.textract_client.analyze_document(
            Document={'Bytes': image_bytes},
            FeatureTypes=['FORMS', 'TABLES']
        )

        vendor = None
        date = None
        total = None
        line_items = []

        for block in response['Blocks']:
            if block['BlockType'] == 'KEY_VALUE_SET':
                if 'VENDOR' in block['Text']:
                    vendor = block['Text'].split('VENDOR')[1].strip()
                elif 'DATE' in block['Text']:
                    date = block['Text'].split('DATE')[1].strip()
                elif 'TOTAL' in block['Text']:
                    total = block['Text'].split('TOTAL')[1].strip()
            elif block['BlockType'] == 'TABLE':
                for relationship in block['Relationships']:
                    if relationship['Type'] == 'CHILD':
                        for child_id in relationship['Ids']:
                            child_block = next(b for b in response['Blocks'] if b['Id'] == child_id)
                            if child_block['BlockType'] == 'CELL':
                                line_items.append(child_block['Text'].strip())

        return {
            'vendor': vendor,
            'date': date,
            'total': total,
            'line_items': line_items
        }
